import re
ansi_text = "hello \x1b7 world \x1b[7m styled world \x1b[0m end"
re_ansi = re.compile(
    r"""
(?:\\x1b\\](.*?)\\x1b\\\\)|
(?:\\x1b([0-?@-Z\\\\-_]|\\[[0-?]*[ -/]*[@-~]))
    """,
    re.VERBOSE,
)
position = 0
tokens = []
for match in re_ansi.finditer(ansi_text):
    start, end = match.span(0)
    osc, sgr = match.groups()
    if start > position:
        tokens.append(("plain", ansi_text[position:start]))
    if sgr:
        if sgr == "(":
            pass
        elif sgr.endswith("m"):
            tokens.append(("sgr", sgr[1:-1]))
        else:
            tokens.append(("stripped", sgr))
    elif osc:
        tokens.append(("osc", osc))
    position = end
if position < len(ansi_text):
    tokens.append(("plain", ansi_text[position:]))

for t in tokens:
    print(t)
